import{_ as o,o as a,c as d,a2 as c}from"./chunks/framework.CnJ-JtFX.js";const p=JSON.parse('{"title":"EP.04 表单不是输入框，是一棵字段树","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.04-formily-basics.md","filePath":"comics/EP.04-formily-basics.md","lastUpdated":1792683644000}'),r={name:"comics/EP.04-formily-basics.md"};function i(t,e,l,s,m,n){return a(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="ep-04-表单不是输入框-是一棵字段树" tabindex="-1">EP.04 表单不是输入框，是一棵字段树 <a class="header-anchor" href="#ep-04-表单不是输入框-是一棵字段树" aria-label="Permalink to &quot;EP.04 表单不是输入框，是一棵字段树&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/04-formily-basics">guide/04-formily-basics</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>困境</strong>：标签君用受控组件加 <code>useState</code> 堆出订单表单，第一版能跑；随后联动、计算、异步查重依次到来，规则散进八个 <code>useEffect</code>，改一处要读十处。</li><li><strong>揭秘</strong>：码叔指出表单不是输入框的集合，而是一棵字段树。Form 持有字段与值，Field 持有单个字段的状态，Schema 只描述结构与规则。</li><li><strong>实证</strong>：像素酱用四个约定键拆解 Schema：<code>type</code> 管结构，<code>x-component</code> 管控件，<code>x-decorator</code> 管包裹，<code>x-validator</code> 管校验。</li><li><strong>结案</strong>：码叔给出最小闭环顺序：先 <code>createForm</code>，再注册组件，再装配 <code>Form + SchemaField</code>，最后用 <code>onAutoSubmit</code> 拿校验后的值。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-规则为什么会散" tabindex="-1">第一格：规则为什么会散 <a class="header-anchor" href="#第一格-规则为什么会散" aria-label="Permalink to &quot;第一格：规则为什么会散&quot;">​</a></h3><p>受控组件的写法把「值」放在父组件，把「规则」放在事件回调里。字段越多，父组件越像一个手写的调度中心：某个字段该不该显示、该不该禁用、值要不要清空，全靠回调里的条件判断。问题不是代码行数，而是没有单一事实来源。</p><p>漫画里的代码芯片列了四周的变化：第一周堆表单，第二周加联动，第三周加计算，第四周已经说不清谁禁用了谁。每一周都在原有结构上打补丁，补丁之间还会互相影响。Formily 的思路是把这些规则搬进字段模型，让框架维护关系图。</p><p>对应正文：<a href="./../guide/04-formily-basics#原理拆解">原理拆解</a>。</p><h3 id="第二格-form、field、schema-的分工" tabindex="-1">第二格：Form、Field、Schema 的分工 <a class="header-anchor" href="#第二格-form、field、schema-的分工" aria-label="Permalink to &quot;第二格：Form、Field、Schema 的分工&quot;">​</a></h3><ul><li><strong>Form</strong>：表单实例，持有字段树、<code>values</code>、校验状态与生命周期钩子。</li><li><strong>Field</strong>：字段实例，持有 <code>value</code>、<code>errors</code>、<code>visible</code>、<code>disabled</code>、<code>loading</code> 等状态。</li><li><strong>Schema</strong>：普通对象，只描述「有哪些字段、用什么组件、有什么规则」，不持有运行时状态。</li></ul><p>输入的数据流是单向的：控件调用 <code>field.onChange</code>，Field 更新值并通知 Form，Form 重算依赖字段，最后触发校验。提交时 Form 把字段值拼成嵌套对象。整个过程没有组件之间的互相传值，只有字段与表单之间的模型通信。</p><h3 id="第三格-四个约定键" tabindex="-1">第三格：四个约定键 <a class="header-anchor" href="#第三格-四个约定键" aria-label="Permalink to &quot;第三格：四个约定键&quot;">​</a></h3><p><code>type</code> 决定字段类型；<code>x-component</code> 是控件名，必须在注册表里存在；<code>x-decorator</code> 通常是 <code>FormItem</code>，负责标题、错误信息与布局；<code>x-validator</code> 可以是对象、数组或函数。</p><p>数组字段还有额外约定：数组级 <code>properties</code> 放 <code>ArrayItems.Addition</code>（添加按钮），每项的 <code>properties</code> 放 <code>ArrayItems.Remove</code>（删除按钮）。这个分工对应「集合操作」与「元素操作」，位置写错会出现「每行都有添加按钮」或「不知道删哪一项」。</p><h3 id="第四格-最小闭环的顺序" tabindex="-1">第四格：最小闭环的顺序 <a class="header-anchor" href="#第四格-最小闭环的顺序" aria-label="Permalink to &quot;第四格：最小闭环的顺序&quot;">​</a></h3><ol><li><code>createForm()</code> 放在 <code>useMemo</code> 里，保证表单实例与组件生命周期对齐；</li><li><code>createSchemaField({ components })</code> 把字符串名映射到真实组件；</li><li><code>&lt;Form form={form}&gt;</code> 提供上下文，<code>&lt;SchemaField schema={schema} /&gt;</code> 递归渲染；</li><li><code>onAutoSubmit</code> 只在校验通过后触发，拿到的是完整的嵌套 <code>values</code>。</li></ol><p>顺序不能反。先建实例再注册组件，是因为 Schema 解析时需要注册表；把 <code>createForm</code> 放进渲染函数，则会在每次重渲染时丢掉用户输入。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>把 <code>createForm()</code> 写在组件体里</strong>：每次渲染新建实例，输入到一半状态就丢了。</li><li><strong>把组件对象直接塞进 Schema</strong>：Schema 无法序列化，后续存库、跨端、做 diff 都会失败。</li><li><strong>数组的添加与删除放错层级</strong>：添加按钮放数组级 <code>properties</code>，删除按钮放 <code>items.properties</code>。</li><li><strong>把字段状态写进 <code>x-component-props</code></strong>：<code>disabled</code>、<code>visible</code>、<code>value</code> 属于字段状态，应交给 reactions 或表单控制。</li><li><strong>以为 <code>default</code> 是控件默认值</strong>：它是字段初始值，参与 <code>values</code>、校验与 Reset。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. Form、Field、Schema 各自持有什么？</b></summary><p>Form 持有整棵字段树、值集合、校验状态与生命周期；Field 持有单个字段的值、错误、可见性、禁用等状态；Schema 只描述结构、控件、校验等静态信息，不持有运行时状态。</p></details><details><summary><b>2. 为什么表单实例必须放在 `useMemo` 里？</b></summary><p>因为表单实例是字段状态的容器。组件每次重渲染都新建实例，会让字段树重建、用户输入丢失、联动关系重置。<code>useMemo</code> 保证实例只创建一次，并与组件生命周期对齐。</p></details><details><summary><b>3. 订单明细的添加按钮应该写在哪里？</b></summary><p>写在数组字段的 <code>properties</code> 里，类型为 <code>void</code>，<code>x-component</code> 为 <code>ArrayItems.Addition</code>。删除按钮则写在 <code>items.properties</code> 里，对应 <code>ArrayItems.Remove</code>。前者是集合级操作，后者是元素级操作。</p></details><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./../guide/04-formily-basics">第 04 章正文</a></li><li><a href="./../guide/05-formily-linkage">第 05 章 · 联动与异步校验</a></li><li><a href="./../appendix/glossary">术语表</a></li></ul>',26)])])}const u=o(r,[["render",i]]);export{p as __pageData,u as default};
